CREATE     PROCEDURE [synapse_fo].[usp_Insert_BUDGETRESERVATIONHEADER_PSN]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:39
	Description: Insert stored procedure for BUDGETRESERVATIONHEADER_PSN from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[BUDGETRESERVATIONHEADER_PSN]
	(
		[ACCOUNTINGDATE],
		[ACCOUNTINGDISTRIBUTIONTEMPLATE],
		[BUDGETRESERVATIONTYPE_PSN],
		[CANCELDATE],
		[CARRIEDFORWARDBUDGETTRANSACTIONHEADER],
		[CREATEDDATETIME],
		[DATAAREAID],
		[DataLakeModified_DateTime],
		[DEPARTMENTREFERENCE],
		[DOCUMENTNUMBER],
		[DOCUMENTSTATUS],
		[DOCUMENTTITLE],
		[ENDDATE],
		[EXTERNALREFERENCE],
		[FileName],
		[FINALIZECLOSINGDATE],
		[LastProcessedChange_DateTime],
		[LASTSAVEDACCOUNTINGDATE],
		[LEDGERVOUCHER],
		[LSN],
		[PARTITION],
		[PSNISCORRECTION],
		[REASONTABLEREF],
		[RECID],
		[RECVERSION],
		[RELIEVINGDOCUMENTTYPE],
		[SOURCEDOCUMENTHEADER],
		[STARTDATE],
		[SysRowId],
		[WORKFLOWSTATUS]
	)
	SELECT 
		stg.[ACCOUNTINGDATE],
		stg.[ACCOUNTINGDISTRIBUTIONTEMPLATE],
		stg.[BUDGETRESERVATIONTYPE_PSN],
		stg.[CANCELDATE],
		stg.[CARRIEDFORWARDBUDGETTRANSACTIONHEADER],
		stg.[CREATEDDATETIME],
		stg.[DATAAREAID],
		stg.[DataLakeModified_DateTime],
		stg.[DEPARTMENTREFERENCE],
		stg.[DOCUMENTNUMBER],
		stg.[DOCUMENTSTATUS],
		stg.[DOCUMENTTITLE],
		stg.[ENDDATE],
		stg.[EXTERNALREFERENCE],
		stg.[FileName],
		stg.[FINALIZECLOSINGDATE],
		stg.[LastProcessedChange_DateTime],
		stg.[LASTSAVEDACCOUNTINGDATE],
		stg.[LEDGERVOUCHER],
		stg.[LSN],
		stg.[PARTITION],
		stg.[PSNISCORRECTION],
		stg.[REASONTABLEREF],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[RELIEVINGDOCUMENTTYPE],
		stg.[SOURCEDOCUMENTHEADER],
		stg.[STARTDATE],
		stg.[SysRowId],
		stg.[WORKFLOWSTATUS]	
	FROM [staging_fo].[BUDGETRESERVATIONHEADER_PSN] stg
		LEFT JOIN [synapse_fo].[BUDGETRESERVATIONHEADER_PSN] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
